import re


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    token_pattern = re.compile(
        r"SUM|MIN|MAX|IF|[A-Z][1-9][0-9]?|[0-9]+|<>|<=|>=|[()+*/,:<>=-]"
    )
    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 1, "<>": 1, "<": 1, "<=": 1, ">": 1, ">=": 1,
        "+": 2, "-": 2,
        "*": 3, "/": 3,
        "neg": 4,
        ":": 5,
    }

    def parse_integer(text):
        # Chunking also supports literals beyond Python's decimal conversion limit.
        text = text.strip()
        sign = 1
        if text.startswith("-"):
            sign = -1
            text = text[1:]
        elif text.startswith("+"):
            text = text[1:]
        value = 0
        for i in range(0, len(text), 9):
            chunk = text[i:i + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return sign * value

    def parse(formula):
        nodes = []
        operators = []
        argument_counts = []
        expect_operand = True

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                nodes.append(("neg", nodes.pop()))
                return

            right = nodes.pop()
            left = nodes.pop()
            if op == ":":
                a, b = left[1], right[1]
                c1, c2 = ord(a[0]), ord(b[0])
                r1, r2 = int(a[1:]), int(b[1:])
                nodes.append((
                    "range",
                    min(c1, c2), max(c1, c2),
                    min(r1, r2), max(r1, r2),
                ))
            else:
                nodes.append((op, left, right))

        for match in token_pattern.finditer(formula):
            token = match.group()

            if token[0].isdigit():
                nodes.append(("number", parse_integer(token)))
                expect_operand = False
            elif token in functions:
                operators.append(token)
                expect_operand = True
            elif token[0].isalpha():
                nodes.append(("reference", token))
                expect_operand = False
            elif token == "(":
                operators.append("(")
                argument_counts.append(1)
                expect_operand = True
            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                argument_counts[-1] += 1
                expect_operand = True
            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()
                count = argument_counts.pop()
                if operators and operators[-1] in functions:
                    function = operators.pop()
                    arguments = tuple(nodes[-count:])
                    del nodes[-count:]
                    if function == "IF":
                        nodes.append(("IF", *arguments))
                    else:
                        nodes.append((function, arguments))
                expect_operand = False
            elif token == "-" and expect_operand:
                operators.append("neg")
            else:
                while (
                    operators
                    and operators[-1] in precedence
                    and precedence[operators[-1]] >= precedence[token]
                ):
                    reduce_operator()
                operators.append(token)
                expect_operand = True

        while operators:
            reduce_operator()
        return nodes[0]

    def expand_arguments(arguments):
        for argument in arguments:
            if argument[0] != "range":
                yield argument
                continue

            _, first_column, last_column, first_row, last_row = argument
            for row in range(first_row, last_row + 1):
                for column in range(first_column, last_column + 1):
                    name = chr(column) + str(row)
                    if name in cells:
                        yield ("reference", name)

    def apply_operator(op, left, right):
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if op == "/":
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if op == "=":
            return left == right
        if op == "<>":
            return left != right
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        if op == ">":
            return left > right
        return left >= right

    memo = {}
    active = set()

    for root in cells:
        if root in memo:
            continue

        tasks = [("cell", root)]
        values = []

        while tasks:
            task = tasks.pop()
            action = task[0]

            if action == "cell":
                name = task[1]
                if name in memo:
                    values.append(memo[name])
                elif name not in cells:
                    values.append(0)
                elif name in active:
                    values.append("#CYCLE!")
                else:
                    content = cells[name]
                    if not content.startswith("="):
                        value = parse_integer(content)
                        memo[name] = value
                        values.append(value)
                    else:
                        node = parse(content[1:])
                        active.add(name)
                        tasks.append(("store", name))
                        tasks.append(("evaluate", node))

            elif action == "store":
                name = task[1]
                memo[name] = values[-1]
                active.remove(name)

            elif action == "evaluate":
                node = task[1]
                kind = node[0]

                if kind == "number":
                    values.append(node[1])
                elif kind == "reference":
                    tasks.append(("cell", node[1]))
                elif kind == "neg":
                    tasks.append(("negate",))
                    tasks.append(("evaluate", node[1]))
                elif kind == "IF":
                    tasks.append(("choose", node[2], node[3]))
                    tasks.append(("evaluate", node[1]))
                elif kind in ("SUM", "MIN", "MAX"):
                    iterator = expand_arguments(node[1])
                    tasks.append(("next_argument", kind, iterator, None))
                else:
                    tasks.append(("left_done", kind, node[2]))
                    tasks.append(("evaluate", node[1]))

            elif action == "negate":
                value = values.pop()
                values.append(value if isinstance(value, str) else -value)

            elif action == "left_done":
                left = values.pop()
                if isinstance(left, str):
                    values.append(left)
                else:
                    tasks.append(("right_done", task[1], left))
                    tasks.append(("evaluate", task[2]))

            elif action == "right_done":
                right = values.pop()
                if isinstance(right, str):
                    values.append(right)
                else:
                    values.append(apply_operator(task[1], task[2], right))

            elif action == "choose":
                condition = values.pop()
                if isinstance(condition, str):
                    values.append(condition)
                else:
                    branch = task[1] if condition else task[2]
                    tasks.append(("evaluate", branch))

            elif action == "next_argument":
                _, function, iterator, accumulator = task
                argument = next(iterator, None)
                if argument is None:
                    values.append(0 if accumulator is None else accumulator)
                else:
                    tasks.append((
                        "argument_done", function, iterator, accumulator
                    ))
                    tasks.append(("evaluate", argument))

            elif action == "argument_done":
                _, function, iterator, accumulator = task
                value = values.pop()
                if isinstance(value, str):
                    values.append(value)
                    continue

                if accumulator is None:
                    accumulator = value
                elif function == "SUM":
                    accumulator += value
                elif function == "MIN":
                    accumulator = min(accumulator, value)
                else:
                    accumulator = max(accumulator, value)

                tasks.append((
                    "next_argument", function, iterator, accumulator
                ))

    return {name: memo[name] for name in cells}
